import{_ as n,o as r,c as a,ah as i}from"./chunks/framework.DDXs_i7t.js";const f=JSON.parse('{"title":"Recherche: Die Inseraten-Affäre (Gekaufte Meinung)","description":"","frontmatter":{},"headers":[],"relativePath":"recherche/inseraten-affaere.md","filePath":"recherche/inseraten-affaere.md"}'),t={name:"recherche/inseraten-affaere.md"};function s(h,e,u,d,l,o){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="recherche-die-inseraten-affare-gekaufte-meinung" tabindex="-1">Recherche: Die Inseraten-Affäre (Gekaufte Meinung) <a class="header-anchor" href="#recherche-die-inseraten-affare-gekaufte-meinung" aria-label="Permalink to &quot;Recherche: Die Inseraten-Affäre (Gekaufte Meinung)&quot;">​</a></h1><p>In unserer Mockumentary untersuchen wir, wie man sich die Gunst der Presse nicht nur verdient, sondern schlichtweg kauft. Die Inseraten-Affäre der Ära Kurz ist hierfür das Lehrstück des 21. Jahrhunderts.</p><h2 id="das-prinzip" tabindex="-1">Das Prinzip <a class="header-anchor" href="#das-prinzip" aria-label="Permalink to &quot;Das Prinzip&quot;">​</a></h2><p>Steuergelder aus dem Finanzministerium wurden (mutmaßlich) für geschönte Umfragen in Boulevardzeitungen verwendet. Das Ziel: Ein künstliches Bild von Erfolg zu schaffen, das dann zum echten Erfolg führt.</p><h2 id="horten-parallele" tabindex="-1">Horten-Parallele <a class="header-anchor" href="#horten-parallele" aria-label="Permalink to &quot;Horten-Parallele&quot;">​</a></h2><p>Helmut Horten wusste schon früh: Wer die Schaufenster kontrolliert, kontrolliert die Begehrlichkeiten. In der Inseraten-Affäre wurden die Zeitungen zu den Schaufenstern der Macht.</p><hr><h2 id="die-gegenoffensive-die-„schlacht-der-gutachten-stand-april-2026" tabindex="-1">Die Gegenoffensive: Die „Schlacht der Gutachten“ (Stand April 2026) <a class="header-anchor" href="#die-gegenoffensive-die-„schlacht-der-gutachten-stand-april-2026" aria-label="Permalink to &quot;Die Gegenoffensive: Die „Schlacht der Gutachten“ (Stand April 2026)&quot;">​</a></h2><p>Im April 2026 hat die Verteidigung von Eva Dichand und Wolfgang Jansky (<em>Heute</em>) eine massive juristische und wissenschaftliche Gegenoffensive gestartet.</p><h3 id="_1-die-wu-studie-statistik-gegen-vorwurf" tabindex="-1">1. Die WU-Studie: Statistik gegen Vorwurf <a class="header-anchor" href="#_1-die-wu-studie-statistik-gegen-vorwurf" aria-label="Permalink to &quot;1. Die WU-Studie: Statistik gegen Vorwurf&quot;">​</a></h3><p>Die Anwälte Michael Rami und Johann Pauer präsentierten eine Studie der Wirtschaftsuniversität Wien (WU).</p><ul><li><strong>Methodik:</strong> Analyse von über 250.000 Artikeln (2016–2021) mittels KI.</li><li><strong>Ergebnis:</strong> Laut Studie gab es keine „wohlwollende Berichterstattung“ für Sebastian Kurz oder die ÖVP in <em>Heute</em>. Die SPÖ habe in diesem Zeitraum sogar die positivsten Bewertungen erhalten.</li><li><strong>Argument:</strong> Wenn es keine Gegenleistung („Wohlwollen“) gab, kann es auch keine Bestechung durch Inserate gegeben haben.</li></ul><h3 id="_2-angriff-auf-den-kronzeugen-thomas-schmid" tabindex="-1">2. Angriff auf den Kronzeugen Thomas Schmid <a class="header-anchor" href="#_2-angriff-auf-den-kronzeugen-thomas-schmid" aria-label="Permalink to &quot;2. Angriff auf den Kronzeugen Thomas Schmid&quot;">​</a></h3><p>Die Verteidigung fordert eine „widersprüchliche Einvernahme“ von Thomas Schmid. Sie werfen ihm vor, dass seine Aussagen zum „Grundübereinkommen“ lediglich auf Annahmen und nicht auf Fakten basierten.</p><h3 id="_3-relevanz-fur-das-horten-mysterium" tabindex="-1">3. Relevanz für das Horten-Mysterium <a class="header-anchor" href="#_3-relevanz-fur-das-horten-mysterium" aria-label="Permalink to &quot;3. Relevanz für das Horten-Mysterium&quot;">​</a></h3><p>Diese Entwicklung ist ein Paradebeispiel für „Scientific Washing“ in Machtstrukturen. Man versucht, moralisch belastende Chats durch abstrakte Statistiken wegzurechnen. In der Mockumentary nutzen wir dies, um zu zeigen, wie Macht versucht, die Realität durch Gutachten neu zu definieren.</p><p><em>Stand der Recherche: 07. April 2026.</em></p>',17)])])}const g=n(t,[["render",s]]);export{f as __pageData,g as default};
